function modal(h){const m=document.createElement('div');m.className='ov';m.innerHTML='<div class="md">'+h+'</div>';m.onclick=e=>{if(e.target===m)m.remove()};document.body.append(m);return m}
const shrink=f=>new Promise(r=>{const i=new Image(),u=URL.createObjectURL(f);i.onload=()=>{const k=Math.min(1,260/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);URL.revokeObjectURL(u);r(c.toDataURL('image/jpeg',.7))};i.onerror=()=>r('');i.src=u});
function fld(f,v){const val=v[f.k]??'',d=f.ltr?' dir="ltr"':'';
 if(f.t==='select')return `<select name="${f.k}">${f.o.map(o=>`<option value="${o[0]}"${val==o[0]?' selected':''}>${o[1]}</option>`).join('')}</select>`;
 if(f.t==='textarea')return `<textarea name="${f.k}" rows="${f.r||4}"${d}>${esc(val)}</textarea>`;
 return `<input name="${f.k}" type="${f.t||'text'}"${f.t==='file'?' accept="image/*"':''} value="${f.t==='file'?'':esc(val)}"${d}>`}
function form(title,fields,v,ok,o={}){
 const m=modal(`<h2>${title}</h2><div class="g">${fields.map(f=>`<label class="${f.w?'w':''}">${f.l}${fld(f,v)}</label>`).join('')}</div>${o.extra||''}<div class="bar">${o.del?'<button class="btn dn" data-d>حذف</button>':''}<span class="sp"></span><button class="btn" data-c>انصراف</button><button class="btn p" data-ok>ذخیره</button></div>`);
 $('[data-c]',m).onclick=()=>m.remove();
 if(o.del)$('[data-d]',m).onclick=()=>ask('مطمئن هستید؟ این کار برگشت ندارد.',()=>{m.remove();o.del()});
