 $('[data-ok]',m).onclick=async()=>{const r={};let bad=0;for(const el of m.querySelectorAll('[name]')){const f=fields.find(x=>x.k===el.name);if(el.type==='file'){if(el.files[0])r[el.name]=await shrink(el.files[0]);continue}r[el.name]=el.value.trim();if(f.req&&!r[el.name]){bad=1;el.classList.add('bad')}}
  if(bad)return toast('لطفاً کادر قرمز را پر کنید');r.months=[...m.querySelectorAll('[data-mo]')].map(b=>b.classList.contains('on'));m.remove();ok(r)};
